import base64
import gmpy2
import random
def commit():
    p=gmpy2.mpz('',16)
    g=gmpy2.mpz(2)
    i=gmpy2.mpz('CE45361C55D328665B3DC2007CB8A163E6492B1F1E',16)
    q=hex(gmpy2.powmod(g,i,p))
    print("GROUP",hex(p)[2:],g,q[2:],"\n")
    #clé secrète
    x=gmpy2.mpz("",16)
    #clé publique
    h=gmpy2.powmod(g,x,p)
    print("PKEY",hex(h))
    #produire aléatoire
    y=random.randint(1, p)
    coup=input("enter coup")
    m = int(bytes(coup, encoding='utf-8').hex(), 16)
    c1 = gmpy2.powmod(g,y,p)
    c2 =  gmpy2.f_mod(gmpy2.mul(m,gmpy2.powmod(h,y,p)), p)
    print("COMMIT",hex(c1)[2:],hex(c2)[2:])
    print("OPEN",hex(y)[2:])